mapper.select:
SELECT 
FROM CAM_RU_JOB_METRIC
WHERE partition_id = #{partitionId} AND job_type = #{key.jobType}
  AND tenant_id = #{key.tenantId} AND worker = #{key.workerName}

mapper.update:
UPDATE CAM_RU_JOB_METRIC
SET created_count = #{row.createdCount},
  created_last_updated_at = #{row.createdLastUpdatedAt},
  completed_count = #{row.completedCount},
  completed_last_updated_at = #{row.completedLastUpdatedAt},
  failed_count = #{row.failedCount},
  failed_last_updated_at = #{row.failedLastUpdatedAt}
WHERE partition_id = #{partitionId} AND job_type = #{row.jobType}
  AND tenant_id = #{row.tenantId} AND worker = #{row.workerName}

mapper.delete:
DELETE FROM CAM_RU_JOB_METRIC
WHERE partition_id = #{partitionId} AND job_type = #{key.jobType}
  AND tenant_id = #{key.tenantId} AND worker = #{key.workerName}
